package android.content;public class Context{private final java.io.File database;public Context(java.io.File database){this.database=database;}public java.io.File getDatabasePath(String name){return database;}public java.io.File getFilesDir(){java.io.File f=new java.io.File(database.getParentFile().getParentFile(),"files");f.mkdirs();return f;}public android.content.res.AssetManager getAssets(){return new android.content.res.AssetManager();}public Context getApplicationContext(){return this;}}